when.condition:
@{
        var body = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
        var allowed = new [] { "journey_id", "journey_state", "intent", "channel", "accessibility_mode" };
        foreach (var p in body.Properties()) { if (!allowed.Contains(p.Name)) { return true; } }
        return false; }
